const manifest = {
  budgets: { longestFit: true },
  memory: { decayProven: true },
  registry: { selectionTests: '6/6' },
  loops: { termination: true },
  errors: { classes: 5 },
  traces: { deterministic: true },
  guards: { attackGold: '9/9' },
  eval: { gold: 15 },
};
const checks = [
  ['budgets fit', manifest.budgets.longestFit === true],
  ['memory decays', manifest.memory.decayProven === true],
  ['registry tested', manifest.registry.selectionTests === '6/6'],
  ['loops terminate', manifest.loops.termination === true],
  ['errors classified', manifest.errors.classes === 5],
  ['traces replay', manifest.traces.deterministic === true],
  ['guards proven', manifest.guards.attackGold === '9/9'],
  ['eval sized', manifest.eval.gold >= 12],
];
for (const [label, ok] of checks) console.log((ok ? 'PASS ' : 'FAIL ') + label);
console.log(checks.every(([, ok]) => ok) ? 'manifest sound' : 'manifest BROKEN');

